module asyn_fifo #(
    parameter	WIDTH = 8,
    parameter 	DEPTH = 16,
    parameter ADDR_WIDTH = $clog2(DEPTH)
) (
    input 					wclk,
    input 					rclk,
    input 					wrstn,
    input					rrstn,
    input 					winc,
    input 			 		rinc,
    input 		[WIDTH-1:0]	wdata,
    output wire				wfull,
    output wire				rempty,
    output wire [WIDTH-1:0]	rdata
);

    reg [WIDTH-1:0] ram [0:DEPTH-1];
    reg [$clog2(DEPTH)-1:0] wp, rp;
    reg [$clog2(DEPTH)-1:0] wp_gray, rp_gray;

    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            wp <= 0;
        end else if (winc && !wfull) begin
            wp <= wp + 1;
        end
    end

    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            rp <= 0;
        end else if (rinc && !rempty) begin
            rp <= rp + 1;
        end
    end

    assign wp_gray = wp ^ (wp >> 1);
    assign rp_gray = rp ^ (rp >> 1);

    assign wfull = (wp_gray == {~rp_gray[ADDR_WIDTH-1], rp_gray[ADDR_WIDTH-2:0]});
    assign rempty = (wp_gray == rp_gray);

    assign rdata = ram[rp];

endmodule

module dual_port_RAM #(parameter DEPTH = 16,  parameter WIDTH = 8)
(
	 input wclk	,
	 input wenc	,
	 input [$clog2(DEPTH)-1:0] waddr  ,
	 input [WIDTH-1:0] wdata ,
	 input rclk	,
	 input renc	,
	 input [$clog2(DEPTH)-1:0] raddr ,
	 output reg [WIDTH-1:0] rdata 		
);

reg [WIDTH-1:0] RAM_MEM [0:DEPTH-1];

always @(posedge wclk) begin
	if(wenc)
		RAM_MEM[waddr] <= wdata;
end 

always @(posedge rclk) begin
	if(renc)
		rdata <= RAM_MEM[raddr];
end 

endmodule
